import { useState } from "react";

export default function Registration() {
  const [step, setStep]       = useState(1); // 1 = choose role, 2 = details, 3 = done
  const [role, setRole]       = useState(null);
  const [showPass, setShowPass] = useState(false);
  const [form, setForm]       = useState({ fullname: "", email: "", password: "" });

  const roles = [
    { id: "student", label: "Student", emoji: "🎓", desc: "Find internships", sel: "selected-blue", accent: "blue" },
    { id: "company", label: "Company", emoji: "🏢", desc: "Hire interns", sel: "selected-dark", accent: "dark" },
    { id: "admin",   label: "Admin",   emoji: "🏛️", desc: "Manage platform", sel: "selected-green", accent: "green" },
  ];

  const btnClass = role === "company" ? "shimmer-btn-dark" : role === "admin" ? "shimmer-btn-green" : "shimmer-btn";
  const accentText = role === "company" ? "text-slate-700" : role === "admin" ? "text-[#9b4a42]" : "text-[#2E7DF7]";
  const inputCls = role === "company" ? "dark" : role === "admin" ? "green" : "";

  const upd = (k, v) => setForm(f => ({ ...f, [k]: v }));

  // شروط التحقق من البيانات
  const isNameValid = form.fullname.trim().split(" ").filter(Boolean).length >= 2;
  const isEmailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email);
  const isPassValid = form.password.length >= 8;
  const canSubmit = isNameValid && isEmailValid && isPassValid;

  return (
    <div className="min-h-screen bg-cream/30 flex overflow-hidden font-syne">
      
      {/* ── LEFT PANEL ── */}
      <div className="hidden lg:flex lg:w-[44%] bg-slate-900 flex-col justify-between relative p-12 overflow-hidden">
        <div className="absolute inset-0 dot-grid opacity-20" />
        <div className="relative">
          <a href="/" className="font-extrabold text-2xl text-white tracking-tight">
            Stag<span className="text-[#6baed6]">.</span>io
          </a>
          <h2 className="text-white text-4xl font-extrabold mt-20 leading-tight">
            Simple registration for <span className="text-[#6baed6]">everyone.</span>
          </h2>
        </div>
        <p className="relative text-slate-500 text-sm">© 2025–2026 · Stag.io Platform</p>
      </div>

      {/* ── RIGHT PANEL ── */}
      <div className="flex-1 flex flex-col justify-center items-center px-6 py-14 overflow-y-auto">
        <div className="w-full max-w-md">
          
          {/* STEP 1: Role Selection */}
          {step === 1 && (
            <div className="anim-fade-up">
              <h2 className="text-3xl font-extrabold text-slate-900 mb-2">Create account</h2>
              <p className="text-slate-500 mb-8 text-sm">Select your role to continue</p>
              
              <div className="grid grid-cols-3 gap-3 mb-8">
                {roles.map(r => (
                  <div key={r.id} onClick={() => setRole(r.id)} className={`role-card cursor-pointer ${role === r.id ? r.sel : ""}`}>
                    <div className="text-3xl mb-2">{r.emoji}</div>
                    <div className="font-bold text-slate-800 text-sm">{r.label}</div>
                    {role === r.id && <div className={`mt-1 text-[10px] font-bold ${accentText}`}>Selected ✓</div>}
                  </div>
                ))}
              </div>

              <button
                disabled={!role}
                onClick={() => setStep(2)}
                className={`w-full text-white font-semibold py-3.5 rounded-xl transition-all ${role ? btnClass : "bg-slate-200 text-slate-400 cursor-not-allowed"}`}
              >
                Continue →
              </button>
            </div>
          )}

          {/* STEP 2: Minimal Details */}
          {step === 2 && (
            <div className="anim-fade-up">
              <button onClick={() => setStep(1)} className="text-xs text-slate-400 hover:text-slate-600 mb-6 flex items-center gap-1">← Back</button>
              <h2 className="text-3xl font-extrabold text-slate-900 mb-6">Your Details</h2>
              <div className="space-y-5">
                {/* Full Name */}
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-1">Full Name</label>
                  <input
                    className={`input-field ${inputCls} ${form.fullname && !isNameValid ? "border-rose-400" : ""}`}
                    placeholder="First and Last name"
                    value={form.fullname}
                    onChange={e => upd("fullname", e.target.value)}
                  />
                </div>

                {/* Email */}
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-1">Email Address</label>
                  <input
                    type="email"
                    className={`input-field ${inputCls} ${form.email && !isEmailValid ? "border-rose-400" : ""}`}
                    placeholder="example@mail.com"
                    value={form.email}
                    onChange={e => upd("email", e.target.value)}
                  />
                </div>

                {/* Password */}
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-1">Password</label>
                  <div className="relative">
                    <input
                      type={showPass ? "text" : "password"}
                      className={`input-field ${inputCls} pr-12`}
                      placeholder="Min. 8 characters"
                      value={form.password}
                      onChange={e => upd("password", e.target.value)}
                    />
                    <button onClick={() => setShowPass(!showPass)} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400">
                      {showPass ? "🙈" : "👁️"}
                    </button>
                  </div>
                </div>

                {/* Submit Button */}
                <button
                  disabled={!canSubmit}
                  onClick={() => setStep(3)}
                  className={`w-full text-white font-semibold py-3.5 rounded-xl transition-all ${canSubmit ? btnClass : "bg-slate-200 text-slate-400 cursor-not-allowed"}`}
                >
                  Create Account →
                </button>
                
                {!canSubmit && form.password.length > 0 && (
                  <p className="text-[10px] text-center text-rose-500">⚠ Fill all fields correctly (Name, valid Email, 8+ char Password)</p>
                )}
              </div>
            </div>
          )}

          {/* STEP 3: Success */}
          {step === 3 && (
            <div className="anim-scale-in text-center py-8">
              <div className="w-20 h-20 bg-green-100 text-green-600 rounded-full flex items-center justify-center text-4xl mx-auto mb-6">✓</div>
              <h2 className="text-3xl font-extrabold text-slate-900 mb-2">Welcome aboard!</h2>
              <p className="text-slate-500 mb-8">Your account is ready. You can now sign in.</p>
              <a href="/login" className={`block w-full text-white font-semibold py-3.5 rounded-xl ${btnClass}`}>Go to Login</a>
            </div>
          )}
          
          {step < 3 && (
            <p className="text-center text-xs text-slate-400 mt-8">
              Already have an account? <a href="/login" className="text-[#2E7DF7] font-bold hover:underline">Sign in</a>
            </p>
          )}
      </div>
      </div>
    </div>
  );
}
